def parse_duration(s):
    if not s:
        return None
    parts = s.split(':')
    if len(parts) == 1:
        return int(parts[0])
    elif len(parts) == 2:
        return int(parts[0]) * 3600 + int(parts[1]) * 60
    elif len(parts) == 3:
        return int(parts[0]) * 3600 * 24 + int(parts[1]) * 3600 + int(parts[2])
    else:
        return None
```

